function poly(points,fill,stroke=null,lw=1){ctx.beginPath();ctx.moveTo(points[0][0],points[0][1]);for(let i=1;i<points.length;i++)ctx.lineTo(points[i][0],points[i][1]);ctx.closePath();if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=lw;ctx.stroke()}}
function drawSky(){const b=biome(),horizon=h*.44;let g=ctx.createLinearGradient(0,0,0,horizon);g.addColorStop(0,b.sky1);g.addColorStop(1,b.sky2);ctx.fillStyle=g;ctx.fillRect(0,0,w,horizon+2);
const sx=w*(.71+.035*Math.sin(worldT*.08)),sy=horizon*.42,sunR=Math.min(w,h)*.07;let glow=ctx.createRadialGradient(sx,sy,1,sx,sy,sunR*2.7);glow.addColorStop(0,b.sun+'cc');glow.addColorStop(.28,b.sun+'55');glow.addColorStop(1,b.sun+'00');ctx.fillStyle=glow;ctx.fillRect(sx-sunR*3,sy-sunR*3,sunR*6,sunR*6);ctx.fillStyle=b.sun+'dd';ctx.beginPath();ctx.arc(sx,sy,sunR*.72,0,Math.PI*2);ctx.fill();
// distant atmospheric ridges
for(let layer=0;layer<3;layer++){const base=horizon*(.58+layer*.12),amp=horizon*(.13-layer*.025);ctx.beginPath();ctx.moveTo(0,horizon);for(let x=0;x<=w+10;x+=12){let yy=base+Math.sin(x*.006+layer*2.3+worldT*.006*(layer+1))*amp+Math.sin(x*.018+layer)*amp*.28;ctx.lineTo(x,yy)}ctx.lineTo(w,horizon);ctx.closePath();ctx.fillStyle=layer===0?'#384f6277':layer===1?'#253f4caa':'#1c3038';ctx.fill()}
// distant skyline and hills
const cityY=horizon*.83;ctx.fillStyle='#192d39aa';for(let x=-10;x<w+30;x+=rand(17,35)){let bh=rand(horizon*.045,horizon*.25);ctx.fillRect(x,cityY-bh,rand(10,25),bh);if(Math.random()<.14){ctx.fillRect(x+4,cityY-bh+8,2,2)}}
let ground=ctx.createLinearGradient(0,horizon,0,h);ground.addColorStop(0,b.ground);ground.addColorStop(1,'#101c22');ctx.fillStyle=ground;ctx.fillRect(0,horizon,w,h-horizon);
// roadside silhouettes
for(let side of [-1,1])for(let i=0;i<8;i++){const y=horizon+((i*57+worldT*65)%(h*.62));const p=clamp((y-horizon)/(h-horizon),0,1),x=w*.5+side*(w*.14+p*w*.34),s=.25+p*1.35;drawTree(x,y,s,side,b)}
}
function drawTree(x,y,s,side,b){ctx.save();ctx.translate(x,y);ctx.scale(s,s);ctx.fillStyle='#101e23aa';ctx.fillRect(-3,-27,6,30);ctx.fillStyle=side<0?'#172d2c':'#243b33';ctx.beginPath();ctx.moveTo(0,-90);ctx.lineTo(-30,-28);ctx.lineTo(27,-28);ctx.closePath();ctx.fill();ctx.beginPath();ctx.moveTo(0,-65);ctx.lineTo(-37,-6);ctx.lineTo(35,-6);ctx.closePath();ctx.fill();ctx.restore()}
function curveAt(t){return Math.sin(worldT*.22+t*3.1)*.52+Math.sin(worldT*.09+t*6.2)*.22}
function roadPoint(t){const horizon=h*.44;const y=horizon+(h-horizon)*t;const curve=curveAt(t);const center=w*.5+curve*w*.15;const half=w*(.035+.39*Math.pow(t,.85));return{x:center,y,half}}
function drawRoad(){const horizon=h*.44,rows=44;for(let i=0;i<rows;i++){const a=i/rows,b=(i+1)/rows,p1=roadPoint(a),p2=roadPoint(b);const edge= Math.floor((worldT*2+a*13))%2===0;poly([[p1.x-p1.half*1.13,p1.y],[p1.x+p1.half*1.13,p1.y],[p2.x+p2.half*1.13,p2.y],[p2.x-p2.half*1.13,p2.y]],edge?'#dbd5c6':'#b9b8a8');poly([[p1.x-p1.half,p1.y],[p1.x+p1.half,p1.y],[p2.x+p2.half,p2.y],[p2.x-p2.half,p2.y]],edge?biome().road:'#383e43');
// shoulder edging
poly([[p1.x-p1.half*.96,p1.y],[p1.x-p1.half*.91,p1.y],[p2.x-p2.half*.91,p2.y],[p2.x-p2.half*.96,p2.y]],'#f6eee1');poly([[p1.x+p1.half*.91,p1.y],[p1.x+p1.half*.96,p1.y],[p2.x+p2.half*.96,p2.y],[p2.x+p2.half*.91,p2.y]],'#f6eee1');
// lane separators with periodic dashes
const dash=(Math.floor(worldT*1.25+a*10)%2)===0;if(dash&&a>.06){for(let lane=-1;lane<=1;lane+=2){const xa=p1.x+lane*p1.half/3,xb=p2.x+lane*p2.half/3;poly([[xa-1.2,p1.y],[xa+1.2,p1.y],[xb+2.3,p2.y],[xb-2.3,p2.y]],'#ffffffa8')}}}
// edge reflectors
for(let i=0;i<12;i++){const t=((i/12+worldT*.035)%1);if(t<.04)continue;const p=roadPoint(t),sz=1+t*3;for(const s of [-1,1]){ctx.fillStyle='#f9d1a2';ctx.fillRect(p.x+s*p.half*1.1-sz/2,p.y-sz/2,sz,sz)}}
}
function drawRival(x,y,s,color){ctx.save();ctx.translate(x,y);ctx.scale(s,s);ctx.shadowColor='#0009';ctx.shadowBlur=15;ctx.shadowOffsetY=8;ctx.fillStyle='#121820';ctx.fillRect(-31,-28,62,43);ctx.shadowColor='transparent';poly([[-29,-26],[-23,-41],[-13,-49],[13,-49],[24,-39],[29,-26]],color);poly([[-18,-39],[-11,-46],[10,-46],[18,-39]],'#132b3b');ctx.fillStyle='#e7e9e9';ctx.fillRect(-23,-24,8,4);ctx.fillRect(15,-24,8,4);ctx.fillStyle='#090d12';ctx.fillRect(-36,-18,8,16);ctx.fillRect(28,-18,8,16);ctx.restore()}
function drawObject(o){const t=clamp(1-o.z/1900,0,1);if(t<=0)return;const p=roadPoint(t),scale=.12+t*1.35,x=p.x+o.lane*p.half*.62,y=p.y; if(o.type==='coin'||o.type==='nitro'){const s=9+t*24;ctx.save();ctx.translate(x,y-s*1.5);ctx.shadowBlur=18;ctx.shadowColor=o.type==='coin'?'#ffde57':'#55e9ef';ctx.fillStyle=o.type==='coin'?'#ffe273':'#64f0f3';ctx.beginPath();ctx.arc(0,0,s*.56,0,Math.PI*2);ctx.fill();ctx.fillStyle='#59441c';ctx.font=`bold ${s}px sans-serif`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(o.type==='coin'?'◈':'ϟ',0,1);ctx.restore();return}if(o.type==='rival'){drawRival(x,y,scale*.78,o.color);return}const s=scale;ctx.save();ctx.translate(x,y);ctx.scale(s,s);poly([[-16,0],[0,-39],[16,0]],'#ff744e','#ffd2a5',1);poly([[-9,-9],[0,-31],[9,-9]],'#fbc284');ctx.fillStyle='#fff0c8';ctx.fillRect(-3,-19,6,4);ctx.restore()}
function drawPlayerCar(x,y,scale,color,glow=false){ctx.save();ctx.translate(x,y);ctx.scale(scale,scale);ctx.shadowColor=glow?color+'88':'#000a';ctx.shadowBlur=glow?30:18;ctx.shadowOffsetY=10;ctx.fillStyle='#080d12';ctx.beginPath();ctx.ellipse(0,0,70,21,0,0,Math.PI*2);ctx.fill();ctx.shadowColor='transparent';
// wheel silhouettes
ctx.fillStyle='#080b10';ctx.beginPath();ctx.roundRect(-59,-39,18,53,5);ctx.roundRect(41,-39,18,53,5);ctx.fill();ctx.fillStyle='#929ba0';ctx.fillRect(-56,-31,3,28);ctx.fillRect(49,-31,3,28);
const paint=ctx.createLinearGradient(-55,-70,50,5);paint.addColorStop(0,color);paint.addColorStop(.45,color);paint.addColorStop(1,'#8e2028');poly([[-53,-17],[-49,-47],[-38,-66],[-24,-77],[25,-77],[42,-62],[53,-38],[58,-15],[48,0],[-47,0]],paint,'#ffb9aa77',1.5);
// rear glass and roof
poly([[-37,-55],[-23,-72],[20,-72],[36,-56],[25,-42],[-26,-42]],'#142a35');poly([[-33,-55],[-20,-68],[0,-68],[0,-45],[-25,-45]],'#8fc7d166');ctx.strokeStyle='#ffffff88';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-18,-69);ctx.lineTo(-3,-45);ctx.stroke();
poly([[-45,-34],[-28,-40],[28,-40],[45,-33],[39,-20],[-39,-20]],color+'ee');ctx.fillStyle='#20262b';ctx.fillRect(-46,-16,92,10);ctx.fillStyle='#ff3947';ctx.shadowColor='#ff3347';ctx.shadowBlur=12;ctx.fillRect(-47,-28,17,7);ctx.fillRect(30,-28,17,7);ctx.shadowBlur=0;ctx.fillStyle='#ffd8c6';ctx.fillRect(-43,-31,9,2);ctx.fillRect(34,-31,9,2);ctx.fillStyle='#b8c0c5';ctx.fillRect(-15,-12,30,2);ctx.fillStyle='#faf1dc';ctx.font='bold 6px sans-serif';ctx.textAlign='center';ctx.fillText('APEX',0,-22);ctx.restore()}

function drawParticles(dt){for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=120*dt;p.life-=dt;ctx.globalAlpha=clamp(p.life/.8,0,1);ctx.fillStyle=p.color;ctx.fillRect(p.x,p.y,3,3);if(p.life<=0)particles.splice(i,1)}ctx.globalAlpha=1}
function drawScene(dt){ctx.clearRect(0,0,w,h);drawSky();drawRoad();if(mode==='race'){for(const o of [...objects].sort((a,b)=>b.z-a.z))drawObject(o)}const point=roadPoint(.94),carColor=cars[selectedCar].color;let px=point.x+(mode==='race'?carX*point.half*.67:point.half*.19),py=h*.87,scale=mode==='race'?clamp(w/820,1.05,1.62):clamp(w/720,.9,1.9);if(mode==='race'&&(keys.space||touch.boost)){px+=Math.sin(worldT*30)*3;ctx.fillStyle='#ffae5633';ctx.beginPath();ctx.ellipse(px,py+8,78*scale,16*scale,0,0,Math.PI*2);ctx.fill()}drawPlayerCar(px,py,scale,carColor,mode==='race');if(mode==='race'&&speed>25){ctx.globalAlpha=.16;ctx.strokeStyle='#e7f8ff';ctx.lineWidth=1;for(let i=0;i<18;i++){const x=((i*167+worldT*900)%w),y=((i*113+worldT*1200)%h);ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-3,y+rand(18,55));ctx.stroke()}ctx.globalAlpha=1}drawParticles(dt);if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('#toast').classList.remove('show')}}
function frame(now){const dt=Math.min(.05,(now-last)/1000||0);last=now;tick(dt);drawScene(dt);requestAnimationFrame(frame)}requestAnimationFrame(frame);
$('#progressText').textContent=`${String(unlocked).padStart(2,'0')} / 121`;
$('#progressBar').style.width=`${Math.max(3,unlocked/121*100)}%`;
})()
</script>
</body>
</html>

