--- index.html
+++ index.html
@@ -23,4 +23,26 @@
 <div id="garageModal" class="modal"><section class="panel"><div class="panel-head"><div><div class="eyebrow">TUNE YOUR LINE</div><h2>Driver garage</h2><p>Pick a machine. Each class has its own edge.</p></div><button class="close" data-close aria-label="Close">×</button></div><div class="garage-layout"><div class="car-show"><div class="show-car"><div class="show-body" id="showBody"></div><div class="show-window"></div><div class="wheel one"></div><div class="wheel two"></div></div></div><div class="garage-details"><div class="rating" id="carRating">A · 842</div><h3 id="carName">Vortex S</h3><p id="carDesc">A precision-built grand tourer engineered to own the fast line.</p><div id="meters"></div><div class="car-nav" id="carChoices"></div></div></div><div class="panel-footer"><span style="font-size:10px;color:#9eabb6">SELECTED VEHICLE IS READY FOR THE GRID</span><button class="primary" data-close>Confirm ride ↗</button></div></section></div>
 <div id="pauseCard" class="center-card"><div class="eyebrow" style="justify-content:center">TAKE A BREATHER</div><h2>Race paused</h2><p>Your run is saved right where you left it.</p><button class="primary" id="resumeBtn">Back to race ↗</button><button class="secondary" id="quitBtn" style="margin-left:8px">Exit race</button></div>
 <div id="finishCard" class="center-card"><div class="eyebrow" style="justify-content:center">CHECKERED FLAG</div><h2 id="finishTitle">Race complete</h2><p id="finishLine">You made the city look slow.</p><div class="result-stats"><div><b id="finishTime">00:00</b><span>RACE TIME</span></div><div><b id="finishReward">+300</b><span>CREDITS EARNED</span></div><div><b id="finishPlace">1st</b><span>FINISH</span></div></div><button class="primary" id="continueBtn">Continue ↗</button><button class="secondary" id="retryBtn" style="margin-left:8px">Race again</button></div>
 </div>
+<script>
+(()=>{'use strict';
+const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],canvas=$('#scene'),ctx=canvas.getContext('2d');
+const cars=[
+ {name:'Vortex S',tag:'02',color:'#e9614e',rating:842,speed:82,accel:74,handling:79,desc:'A precision-built grand tourer engineered to own the fast line.'},
+ {name:'Kestrel M',tag:'07',color:'#62a9d8',rating:876,speed:78,accel:86,handling:91,desc:'A razor-sharp sport coupe with a taste for tight city corners.'},
+ {name:'Sora GT',tag:'11',color:'#d7d6c6',rating:811,speed:88,accel:72,handling:70,desc:'A high-speed touring machine that eats the longest straights.'},
+ {name:'Radian X',tag:'04',color:'#b680e2',rating:895,speed:86,accel:88,handling:83,desc:'A next-generation electric hypercar. Instant torque. No excuses.'}
+];
+const tracks=['NEON HARBOR','ALPINE PASS','SUNSET STRIP','OLD TOWN','DESERT CIRCUIT','NIGHT CITY'];
+let save={credits:2450,unlocked:1,selected:0,done:[]};try{save={...save,...JSON.parse(localStorage.apexSave||'{}')}}catch{}
+let w=0,h=0,dpr=1,last=0,mode='home',level=1,elapsed=0,carX=0,speed=0,nitro=100,boost=false,steer=0,world=0,objects=[],particles=[],keys={},nextSpawn=0,toast='',toastTime=0;
+function persist(){localStorage.apexSave=JSON.stringify(save);$('#credits').textContent=save.credits.toLocaleString();$('#progressText').textContent=`${String(save.unlocked).padStart(2,'0')} / 121` ;$('#progressBar').style.width=`${Math.max(1,save.unlocked/121*100)}%`;$('#homeCar').textContent=`${cars[save.selected].name.toUpperCase()} / ${cars[save.selected].tag}`}
+function resize(){dpr=Math.min(devicePixelRatio||1,2);w=innerWidth;h=innerHeight;canvas.width=w*dpr;canvas.height=h*dpr;canvas.style.width=w+'px';canvas.style.height=h+'px';ctx.setTransform(dpr,0,0,dpr,0,0)}addEventListener('resize',resize);resize();
