function showToast(t){toast=t;toastTime=1.8}function openModal(id){$('#'+id).classList.add('open')}function closeModals(){$$('.modal').forEach(x=>x.classList.remove('open'))}
function showHome(){mode='home';$('#home').classList.add('active');$('#raceHud').classList.remove('show','paused');$('#pauseCard').classList.remove('open');$('#finishCard').classList.remove('open');persist()}
function startRace(n=save.unlocked){level=n;elapsed=0;speed=0;carX=0;nitro=100;boost=false;objects=[];particles=[];nextSpawn=0;mode='race';closeModals();$('#home').classList.remove('active');$('#raceHud').classList.add('show');$('#raceHud').classList.remove('paused');$('#pauseCard').classList.remove('open');$('#finishCard').classList.remove('open');$('#position').textContent='1 / 4'}
function pause(){if(mode!=='race')return;mode='pause';$('#raceHud').classList.add('paused');$('#pauseCard').classList.add('open')}
function resume(){if(mode!=='pause')return;mode='race';$('#raceHud').classList.remove('paused');$('#pauseCard').classList.remove('open')}
function finish(){if(mode!=='race')return;mode='finish';$('#raceHud').classList.remove('show');$('#finishCard').classList.add('open');let reward=300+Math.floor(nitro*1.5);save.credits+=reward;save.done=save.done||[];if(!save.done.includes(level))save.done.push(level);save.unlocked=Math.min(121,Math.max(save.unlocked,level+1));persist();$('#finishTime').textContent=`00:${String(Math.floor(elapsed)).padStart(2,'0')}`;$('#finishReward').textContent='+'+reward;let place=elapsed<24?'1st':elapsed<29?'2nd':elapsed<34?'3rd':'4th';$('#finishPlace').textContent=place;$('#finishTitle').textContent=place==='1st'?'Clean sweep!':'Race complete';$('#finishLine').textContent=`${tracks[Math.floor((level-1)/21)%6]} · Event ${String(level).padStart(3,'0')}`}
function tick(dt){world+=dt*(mode==='race'?Math.max(.35,speed/150):.42);if(mode!=='race')return;elapsed+=dt;let c=cars[save.selected],accelerating=keys.ArrowUp||keys.w||keys.W;boost=!!(keys.Space||keys.Shift||keys[' ']||touchBoost);let target=accelerating?310:270;speed+=(target-speed)*dt*(c.accel/70);if(boost&&nitro>0){speed=Math.min(360,speed+70*dt);nitro=Math.max(0,nitro-25*dt)}else nitro=Math.min(100,nitro+3*dt);steer=(keys.ArrowLeft||keys.a||keys.A?-1:0)+(keys.ArrowRight||keys.d||keys.D?1:0)+touchSteer;carX=clamp(carX+steer*dt*(1.9+(speed/250)), -.94,.94);if(Math.abs(carX)>.79)speed=Math.max(100,speed-48*dt);nextSpawn-=dt;if(nextSpawn<=0){spawn();nextSpawn=rng(.65,1.05)}for(let i=objects.length-1;i>=0;i--){let o=objects[i];o.z+=dt*(.24+speed/530);if(o.z>.83&&o.z<.97&&Math.abs(o.lane-carX)<.34){if(o.type==='coin'){save.credits+=25;persist();showToast('+25 CREDITS')}else{speed=Math.max(90,speed-62);showToast('TRAFFIC HIT · HOLD YOUR LINE')}objects.splice(i,1);continue}if(o.z>1.08)objects.splice(i,1)}$('#speed').textContent=String(Math.round(speed)).padStart(3,'0');$('#nitroBar').style.width=nitro+'%';let rival=Math.floor(elapsed/12)%3;$('#position').textContent=(elapsed>35?'1':'1')+' / 4';if(elapsed>38)finish()}
let touchSteer=0,touchBoost=false;
$('#playBtn').onclick=()=>openModal('levelModal');$('#levelsBtn').onclick=()=>openModal('levelModal');$$('[data-nav="levels"]').forEach(b=>b.onclick=()=>openModal('levelModal'));$$('[data-nav="garage"]').forEach(b=>b.onclick=()=>openModal('garageModal'));$$('[data-nav="home"]').forEach(b=>b.onclick=showHome);$$('[data-close]').forEach(b=>b.onclick=closeModals);$$('.modal').forEach(m=>m.addEventListener('click',e=>{if(e.target===m)closeModals()}));
function buildLevels(){let grid=$('#levelGrid');grid.innerHTML='';for(let i=1;i<=121;i++){let b=document.createElement('button'),locked=i>save.unlocked;b.className='level'+(locked?' locked':(save.done||[]).includes(i)?' done':'');b.textContent=String(i).padStart(2,'0');b.setAttribute('aria-label',`Level ${i}${locked?', locked':''}`);b.onclick=()=>{if(locked){showToast('WIN THE PREVIOUS RACE TO UNLOCK');setTimeout(()=>{},0)}else startRace(i)};grid.append(b)}}
const meters=$('#meters'),choices=$('#carChoices');function renderGarage(){let c=cars[save.selected];$('#carName').textContent=c.name;$('#carDesc').textContent=c.desc;$('#carRating').textContent=`${c.rating>870?'S':'A'} · ${c.rating}`;$('#showBody').style.background=`linear-gradient(160deg,${c.color},${c.color} 48%,#38232a)`;meters.innerHTML='';[['TOP SPEED',c.speed],['ACCELERATION',c.accel],['HANDLING',c.handling]].forEach(([name,val])=>{let row=document.createElement('div');row.className='meter';row.innerHTML=`<label><span>${name}</span><span>${val}</span></label><i style="--v:${val}%"></i>`;meters.append(row)});choices.innerHTML='';cars.forEach((car,i)=>{let b=document.createElement('button');b.className='car-choice'+(i===save.selected?' selected':'');b.textContent=car.tag;b.onclick=()=>{save.selected=i;persist();renderGarage()};choices.append(b)})}
$$('[data-nav="garage"]').forEach(b=>b.addEventListener('click',renderGarage));$('#pauseBtn').onclick=pause;$('#resumeBtn').onclick=resume;$('#quitBtn').onclick=showHome;$('#continueBtn').onclick=showHome;$('#retryBtn').onclick=()=>startRace(level);$('#continueBtn').addEventListener('click',()=>{$('#finishCard').classList.remove('open')});

