async (page) => {
  await page.evaluate(() => localStorage.clear());
  await page.reload();
  await page.getByRole('button', { name: 'GARAGE' }).click();
  const garageOpen = await page.locator('#garageModal').evaluate(e => e.classList.contains('open'));
  await page.locator('#carChoices button').nth(1).click();
  const picked = await page.locator('#carName').textContent();
  await page.getByRole('button', { name: 'Confirm ride' }).click();
  const homeCar = await page.locator('#homeCar').textContent();
  await page.getByRole('button', { name: 'Start racing' }).click();
  const levelCount = await page.locator('#levelGrid button').count();
  const locked = await page.locator('#levelGrid button').nth(1).evaluate(e => e.classList.contains('locked'));
  await page.locator('#levelGrid button').first().click();
  await page.keyboard.down('ArrowUp');
  await page.keyboard.down('ArrowRight');
  await page.waitForTimeout(1000);
  await page.keyboard.up('ArrowRight');
  await page.keyboard.up('ArrowUp');
  const speed = await page.locator('#speed').textContent();
  await page.locator('#pauseBtn').click();
  const paused = await page.locator('#pauseCard').evaluate(e => e.classList.contains('open'));
  await page.locator('#resumeBtn').click();
  const resumed = await page.locator('#pauseCard').evaluate(e => !e.classList.contains('open'));
  return { garageOpen, picked, homeCar, levelCount, locked, speed, paused, resumed };
}

