async (page) => {
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  await page.setViewportSize({ width: 390, height: 844 });
  const mobileControls = await page.locator('.touch-controls').evaluate(e => getComputedStyle(e).display);
  const buttons = await page.locator('.touch-controls button').evaluateAll(xs => xs.map(e => { const r = e.getBoundingClientRect(); return { label: e.getAttribute('aria-label') || e.textContent.trim(), w: r.width, h: r.height, x: r.x, y: r.y }; }));
  await page.locator('#raceHud').evaluate(e => e.classList.remove('show'));
  await page.locator('#home').evaluate(e => e.classList.add('active'));
  await page.locator('#playBtn').click();
  await page.locator('#levelGrid button').first().click();
  await page.locator('[data-boost]').hover();
  await page.mouse.down();
  await page.waitForTimeout(500);
  await page.mouse.up();
  const nitroAfterBoost = await page.locator('#nitroBar').evaluate(e => e.style.width);
  await page.waitForTimeout(39000);
  const finishVisible = await page.locator('#finishCard').evaluate(e => e.classList.contains('open'));
  const credits = await page.locator('#credits').textContent();
  const unlocked = await page.evaluate(() => JSON.parse(localStorage.apexSave).unlocked);
  return { mobileControls, buttons, nitroAfterBoost, finishVisible, credits, unlocked, errors };
}

