async (page) => {
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  await page.setViewportSize({ width: 1280, height: 720 });
  await page.evaluate(() => localStorage.clear());
  await page.reload();
  await page.locator('#playBtn').click();
  await page.locator('#levelGrid button').first().click();
  await page.waitForFunction(() => document.querySelector('#finishCard').classList.contains('open'), null, { timeout: 80000 });
  const result = {
    finishVisible: await page.locator('#finishCard').evaluate(e => e.classList.contains('open')),
    finishTitle: await page.locator('#finishTitle').textContent(),
    credits: await page.locator('#credits').textContent(),
    saved: await page.evaluate(() => JSON.parse(localStorage.apexSave)),
    hudHidden: await page.locator('#raceHud').evaluate(e => !e.classList.contains('show')),
    errors
  };
  await page.locator('#continueBtn').click();
  await page.locator('#levelsBtn').click();
  result.levelTwoUnlocked = await page.locator('#levelGrid button').nth(1).evaluate(e => !e.classList.contains('locked'));
  return result;
}

